files.install.ps1:
# Install tiny - a terminal knowledge manager. Windows.
#
#   irm https://raw.githubusercontent.com/mattsaund/tiny/main/install.ps1 | iex
#
# Downloads the ready-made tiny.exe from the latest GitHub release. Only when
# there is none to download - no release published yet, or a branch asked for
# by name - does it build from source, which on Windows needs Rust and the
# Visual Studio Build Tools; it offers to install both.
#
# Override anything with the environment:
#   $env:TINY_REPO         git URL (default: https://github.com/mattsaund/tiny.git)
#   $env:TINY_REF          branch or tag to build (default: main, which downloads)
#   $env:TINY_PREFIX       where tiny.exe lands (default: %USERPROFILE%\.local\bin)
#   $env:TINY_FROM_SOURCE  set to anything to build instead of downloading
#
# Three rules this file keeps, each because breaking it broke an install:
#
#   * It is plain ASCII. Windows PowerShell 5.1 reads a local .ps1 in the ANSI
#     code page, and the last byte of a UTF-8 em dash is, in that code page, a
#     curly double quote - which PowerShell takes as the end of a string.
#
#   * It never sets $ErrorActionPreference to Stop. 5.1 turns every line a
#     native program writes to stderr into an error record once the stream is
#     redirected, and under Stop into a terminating one. git says "Cloning
#     into..." on stderr and cargo says everything there, so Stop ended the
#     script on the first line of perfectly ordinary output. Failures are
#     checked where they happen instead: $LASTEXITCODE after every program, and
#     -ErrorAction Stop on the few cmdlets whose failure matters.
#
#   * It never calls exit. Piped through iex, this runs in the caller's own
#     session, and an exit there closes the window the user typed into - along
#     with the message saying what went wrong.

& {
    $ErrorActionPreference = 'Continue'

    # GitHub only speaks TLS 1.2 and up, and Windows PowerShell 5.1 on an older
    # Windows does not offer it unless asked.
    [Net.ServicePointManager]::SecurityProtocol =
        [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12

    function Have([string]$Name) {
        [bool](Get-Command $Name -ErrorAction SilentlyContinue)
    }

    # --- the ready-made binary ----------------------------------------------

    # The release workflow's zip for this machine, unpacked into $Prefix.
    # Returns whether it worked. Every way it can fail - no release yet, no
    # network, a repository that is not on GitHub - is a reason to build
    # instead, not a reason to stop.
    function Install-Prebuilt([string]$Repo, [string]$Prefix) {
        $slug = $Repo -replace '^https://github\.com/', '' -replace '\.git$', ''
        if ($slug -match '://' -or $slug -notmatch '^[^/]+/[^/]+$') { return $false }

        # One Windows build, for x64. ARM64 Windows runs it under emulation.
        $asset = 'tiny-x86_64-pc-windows-msvc.zip'
        $url = "https://github.com/$slug/releases/latest/download/$asset"
        $work = Join-Path ([IO.Path]::GetTempPath()) ('tiny-' + [Guid]::NewGuid().ToString('N'))
        New-Item -ItemType Directory -Force -Path $work | Out-Null
        try {
            Write-Host 'downloading tiny ... ' -NoNewline
            $zip = Join-Path $work $asset
            # The progress bar Invoke-WebRequest draws in 5.1 slows a download
            # down by an order of magnitude.
            $ProgressPreference = 'SilentlyContinue'
            try {
                Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $zip -ErrorAction Stop
            }
            catch {
                Write-Host 'none published yet, so building from source instead'
                return $false
            }
            Expand-Archive -Path $zip -DestinationPath $work -Force -ErrorAction Stop
            $exe = Get-ChildItem -Path $work -Filter 'tiny.exe' -Recurse | Select-Object -First 1
            if (-not $exe) {
                Write-Host 'the download had no tiny.exe in it, so building instead'
                return $false
            }
            New-Item -ItemType Directory -Force -Path $Prefix | Out-Null
            Copy-Item -Path $exe.FullName -Destination (Join-Path $Prefix 'tiny.exe') -Force -ErrorAction Stop
            Write-Host 'done'
            return $true
        }
        finally {
            Remove-Item -Recurse -Force $work -ErrorAction SilentlyContinue
        }
    }

    # --- building from source -----------------------------------------------

    # Whether the MSVC build tools are installed.
    #
    # Not Get-Command cl: the compiler is never on PATH outside a Visual Studio
    # developer prompt, even when it is installed - which is why that check
    # told everyone they had no compiler. vswhere is how Rust itself finds it.
    function Test-Msvc {
        $vswhere = Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe'
        if (-not (Test-Path $vswhere)) { return $false }
        $found = & $vswhere -latest -products * `
            -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 `
            -property installationPath 2>$null
        return [bool]$found
    }

    # The Build Tools, offered before Rust rather than after: rustup looks for
    # them as it installs, and finding them already there is what stops it
    # pulling in the whole of Visual Studio on its own account.
    function Confirm-Msvc {
        if (Test-Msvc) { return }
        Write-Host ''
        Write-Host 'Building tiny from source on Windows needs the Visual Studio Build Tools:'
        Write-Host 'the C/C++ compiler and linker Rust uses. They are free, a few gigabytes,'
        Write-Host 'install in the background, and ask for an administrator prompt.'
        $reply = Read-Host 'Install them now? [Y/n]'
        if ($reply -match '^[Nn]') {
            throw 'the Build Tools are needed to build from source: https://visualstudio.microsoft.com/visual-cpp-build-tools/'
        }
        if (-not (Have 'winget')) {
            throw 'winget is not here to install them. Get the Build Tools from https://visualstudio.microsoft.com/visual-cpp-build-tools/ ("Desktop development with C++"), then run this again'
        }
        Write-Host 'installing the Build Tools - this takes a while ...'
        & winget install --id Microsoft.VisualStudio.2022.BuildTools --exact `
            --accept-package-agreements --accept-source-agreements `
            --override '--passive --wait --add Microsoft.VisualStudio.Workload.VCTools --includeRecommended'
        # winget's exit code is not a reliable answer - it is non-zero for
        # "already installed" - so ask the same question again instead.
        if (-not (Test-Msvc)) {
            throw 'the Build Tools did not install; see the message above, or install them by hand and run this again'
        }
    }

    function Confirm-Cargo {
        if (Have 'cargo') { return }
        $cargoBin = Join-Path $HOME '.cargo\bin'
        if (Test-Path (Join-Path $cargoBin 'cargo.exe')) {
            $env:PATH = "$cargoBin;$env:PATH"
            return
        }
        Write-Host ''
        Write-Host 'Building tiny needs Rust, and cargo is not installed. It goes in'
        Write-Host '~\.rustup and ~\.cargo, and "rustup self uninstall" removes it again.'
        $reply = Read-Host 'Install it now? [Y/n]'
        if ($reply -match '^[Nn]') { throw 'cargo is needed to build from source: https://rustup.rs' }
        $init = Join-Path ([IO.Path]::GetTempPath()) 'rustup-init.exe'
        $ProgressPreference = 'SilentlyContinue'
        Invoke-WebRequest -UseBasicParsing -Uri 'https://win.rustup.rs/x86_64' -OutFile $init -ErrorAction Stop
        & $init -y --profile minimal --default-toolchain stable
        $code = $LASTEXITCODE
        Remove-Item $init -ErrorAction SilentlyContinue
        if ($code -ne 0) { throw 'rustup failed; the output above says why' }
        $env:PATH = "$cargoBin;$env:PATH"
        if (-not (Have 'cargo')) { throw 'cargo is still not on PATH' }
    }

    # One line that moves: [#####.......]  42%  compiling syntect
    function Write-Bar([int]$Count, [int]$Total, [string]$What) {
        $width = 28
        $label = if ($What.Length -gt 30) { $What.Substring(0, 30) } else { $What.PadRight(30) }
        if ($Total -le 0) {
            Write-Host ("`r  {0} crates  {1}" -f $Count, $label) -NoNewline
            return
        }
        $percent = [Math]::Min(100, [int]($Count * 100 / $Total))
        $filled = [int]($percent * $width / 100)
        $bar = ('#' * $filled) + ('.' * ($width - $filled))
        Write-Host ("`r  [{0}] {1,3}%  {2}" -f $bar, $percent, $label) -NoNewline
    }

    function Build-Tiny([string]$Source, [string]$Prefix, [string]$Root, [string]$Log) {
        New-Item -ItemType Directory -Force -Path $Prefix | Out-Null
        Write-Host 'building - this takes a minute the first time'

        # How many crates the bar counts against. Asking cargo rather than
        # writing a number down keeps the bar right when the dependencies
        # change; if the question fails the bar counts instead of filling.
        $total = 0
        $tree = & cargo tree --manifest-path (Join-Path $Source 'Cargo.toml') `
            -e 'normal,build' --prefix none --no-dedupe 2>$null
        if ($LASTEXITCODE -eq 0 -and $tree) {
            $total = @($tree | Where-Object { $_.Trim() } | Sort-Object -Unique).Count
        }

        $moving = -not [Console]::IsOutputRedirected
        $done = 0

        # Cargo says what it is doing a line at a time, on stderr. Merged into
        # the pipeline, each line arrives here as it is written; the log keeps
        # all of it for the failure case, where what went wrong matters more
        # than how far it got.
        & cargo install --path $Source --bin tiny --root $Root 2>&1 | ForEach-Object {
            $line = "$_"
            Add-Content -Path $Log -Value $line
            if (-not $moving) { return }
            $trimmed = $line.TrimStart()
            $what = $null
            $count = $done
            if ($trimmed.StartsWith('Compiling ')) {
                $done++
                $name = ($trimmed -split '\s+')[1]
                # tiny is always the last crate, since everything it depends on
                # has to exist first. Its arrival means only the link is left.
                if ($name -eq 'tiny' -and $total -gt 0) {
                    $count = $total - 1
                    $what = 'linking tiny'
                }
                else {
                    $count = $done
                    $what = "compiling $name"
                }
            }
            elseif ($trimmed.StartsWith('Downloaded ')) { $what = 'fetching crates' }
            elseif ($trimmed.StartsWith('Updating ')) { $what = 'updating the crate index' }
            elseif ($trimmed.StartsWith('Finished ')) {
                $count = $total
                $what = 'installing'
            }
            if ($what) { Write-Bar $count $total $what }
        }
        $built = $LASTEXITCODE -eq 0
        if ($moving) { Write-Host '' }
        if (-not $built) {
            Write-Host ''
            if (Test-Path $Log) { Get-Content $Log -Tail 30 | ForEach-Object { Write-Host $_ } }
            throw 'the build failed; the output above says why'
        }
        $exe = Join-Path $Root 'bin\tiny.exe'
        if (-not (Test-Path $exe)) { throw 'the build finished without leaving a tiny.exe' }
        Copy-Item -Path $exe -Destination (Join-Path $Prefix 'tiny.exe') -Force -ErrorAction Stop
    }

    function Install-FromSource([string]$Repo, [string]$Ref, [string]$Prefix, [bool]$Checkout) {
        Confirm-Msvc
        Confirm-Cargo

        $source = $null
        $temp = $false
        $log = Join-Path ([IO.Path]::GetTempPath()) ('tiny-build-' + [Guid]::NewGuid().ToString('N') + '.log')
        # Cargo installs into <root>\bin and keeps its own records in <root>, so
        # it gets a root of its own, thrown away below, and Build-Tiny copies
        # tiny.exe out to $Prefix. Handing it the prefix's parent instead only
        # put the binary in the prefix when the prefix happened to be named bin.
        $root = Join-Path ([IO.Path]::GetTempPath()) ('tiny-root-' + [Guid]::NewGuid().ToString('N'))
        try {
            if ($Checkout) {
                $source = (Get-Location).Path
                Write-Host "building from $source"
            }
            else {
                if (-not (Have 'git')) { throw 'git is needed to fetch the source' }
                $source = Join-Path ([IO.Path]::GetTempPath()) ('tiny-' + [Guid]::NewGuid().ToString('N'))
                $temp = $true
                Write-Host "fetching $Repo ($Ref) ... " -NoNewline
                # Discarded, not merged: git narrates cloning on stderr, and
                # what matters is only whether it worked.
                & git clone --quiet --depth 1 --branch $Ref $Repo $source 2>$null | Out-Null
                if ($LASTEXITCODE -ne 0) {
                    Write-Host ''
                    throw "could not clone $Repo ($Ref)"
                }
                Write-Host 'done'
            }
            Build-Tiny -Source $source -Prefix $Prefix -Root $root -Log $log
        }
        finally {
            if ($temp -and $source -and (Test-Path $source)) {
                Remove-Item -Recurse -Force $source -ErrorAction SilentlyContinue
            }
            if (Test-Path $log) { Remove-Item -Force $log -ErrorAction SilentlyContinue }
            if (Test-Path $root) { Remove-Item -Recurse -Force $root -ErrorAction SilentlyContinue }
        }
    }

    # --- PATH ---------------------------------------------------------------

    # Put $Prefix on the user's PATH, for good and for this window.
    #
    # The *user* PATH is read and written, not the combined one: writing the
    # combined PATH back would copy every system-wide entry into the user's own.
    function Add-ToPath([string]$Prefix) {
        $user = [Environment]::GetEnvironmentVariable('PATH', 'User')
        if (-not $user) { $user = '' }
        $parts = @($user -split ';' | Where-Object { $_ })
        if ($parts -notcontains $Prefix) {
            [Environment]::SetEnvironmentVariable('PATH', (@($parts + $Prefix) -join ';'), 'User')
            Write-Host "added $Prefix to your PATH, so new terminals will find tiny"
        }
        if (@($env:PATH -split ';') -notcontains $Prefix) {
            $env:PATH = "$env:PATH;$Prefix"
        }
    }

    # --- the whole of it ----------------------------------------------------

    function Install-Tiny {
        $repo = if ($env:TINY_REPO) { $env:TINY_REPO } else { 'https://github.com/mattsaund/tiny.git' }
        $ref = if ($env:TINY_REF) { $env:TINY_REF } else { 'main' }
        $prefix = if ($env:TINY_PREFIX) { $env:TINY_PREFIX } else { Join-Path $HOME '.local\bin' }
        $binary = Join-Path $prefix 'tiny.exe'

        # Windows locks a program while it runs, so a running tiny cannot be
        # replaced. Better said now than half way through.
        if (Get-Process -Name tiny -ErrorAction SilentlyContinue) {
            throw 'tiny is running. Close it, then run this again'
        }

        # Running from inside a checkout means "build this", so a checkout
        # never downloads. Nor does naming a ref: a release is a tag, and
        # a branch today is not what the last tag was.
        $checkout = (Test-Path 'Cargo.toml') -and
            (Select-String -Path 'Cargo.toml' -Pattern 'name = "tiny"' -Quiet)
        $installed = $false
        if (-not $checkout -and -not $env:TINY_FROM_SOURCE -and $ref -eq 'main') {
            $installed = Install-Prebuilt -Repo $repo -Prefix $prefix
        }
        if (-not $installed) {
            Install-FromSource -Repo $repo -Ref $ref -Prefix $prefix -Checkout $checkout
        }
        if (-not (Test-Path $binary)) { throw "expected a binary at $binary" }

        Add-ToPath -Prefix $prefix
        Write-Host ''
        Write-Host "installed $binary"
        Write-Host 'run it with:      tiny ~\notes'
        Write-Host 'remove it with:   tiny --uninstall'
    }

    try {
        Install-Tiny
    }
    catch {
        Write-Host ''
        Write-Host "install: $($_.Exception.Message)" -ForegroundColor Red
        # Not exit, which would close the window. A failed exit code is still
        # there for anything that checks - a CI job, a script.
        $global:LASTEXITCODE = 1
    }
}

files.src/app/actions.rs:
//! The plain keys: moving around, opening, folding, refreshing.
//!
//! What is left of the keyboard once the overlays, the commands and the file
//! operations have had their share. These are the ones with no argument, no
//! confirmation and no mode: press the key, something moves.
//!
//! Two of them do two things each, on purpose. Right-arrow expands a folder or
//! steps into an open one or opens a file; left-arrow closes a folder or jumps
//! to the parent. That is what makes them read as "inwards" and "outwards"
//! rather than as four separate keys you have to choose between.

use std::path::PathBuf;

use crate::config::keys::Action;
use crate::files::media;

use super::App;
use super::mode::{Confirm, ConfirmKind, Focus, Mode, Window};
use super::parts::display_name;
use super::preview::Preview;

/// How much of the window one press of the resize keys moves.
///
/// A twentieth: ten presses cross the whole range, which is few enough to be
/// worth holding the key down for and many enough to land where you meant.
const TREE_WIDTH_STEP: f32 = 0.05;

/// The narrowest and widest the browser goes, matching what `Config::sanitized`
/// will accept — a pane the keys could reach but the config would clamp back
/// would be a width that changed by itself on the next restart.
const TREE_WIDTH_MIN: f32 = 0.10;
const TREE_WIDTH_MAX: f32 = 0.60;

impl App {
    // ---- actions ----------------------------------------------------------

    /// Right-arrow on the tree: expand a closed folder, step into an
    /// already-open one, or focus the preview for a file.
    ///
    /// This is the "inwards" key, and the mirror of
    /// [`App::collapse_or_parent`]: holding it down walks you down a branch.
    /// Enter is deliberately different — see [`App::toggle_or_open`].
    pub(super) fn activate(&mut self) {
        let Some(row) = self.selected_row().cloned() else {
            return;
        };
        if row.is_dir {
            if row.expanded {
                self.move_selection(1);
            } else {
                self.tree.expand(&row.path);
                self.rebuild_rows();
            }
        } else {
            self.focus_editor();
        }
    }

    /// Enter on the tree: open a closed folder, close an open one, or focus
    /// the preview for a file.
    ///
    /// Unlike [`App::activate`], the cursor never moves. Pressing Enter twice
    /// on a folder leaves the tree exactly as it was found, which is what most
    /// file browsers do and what the key reads as — one thing, toggled.
    pub(super) fn toggle_or_open(&mut self) {
        let Some(row) = self.selected_row().cloned() else {
            return;
        };
        if row.is_dir {
            self.tree.toggle(&row.path);
            self.rebuild_rows();
        } else {
            self.focus_editor();
        }
    }

    /// Open whatever the cursor is on.
    ///
    /// Every text file opens the same way: into the editor, with the cursor in
    /// it. There is no reading mode to pass through — markdown keeps its
    /// formatting while you edit it (see `ui::live_rows`), so the rendered
    /// view was a step that no longer bought anything.
    ///
    /// A picture or a video is the one thing that opens *out* of tiny, in
    /// whatever program the desktop already uses for it. The keyboard stays on
    /// the tree, because there is nothing in the pane to give it to and
    /// leaving it there means the next arrow key still moves the cursor
    /// instead of needing an Esc first.
    ///
    /// Does nothing for a directory, and explains itself for a binary.
    pub(super) fn focus_editor(&mut self) {
        match &self.preview {
            Preview::Buffer { .. } => {
                self.focus = Focus::Editor;
                self.status = "editing — Ctrl+S save, Esc back".into();
            }
            Preview::Media { path, .. } => {
                let path = path.clone();
                self.status = match media::open_with_desktop(&path) {
                    Ok(()) => format!("opened {} outside tiny", display_name(&path)),
                    Err(e) => format!("{e:#}"),
                };
            }
            Preview::Binary { kind, .. } => {
                self.status = format!("{kind} — not editable");
            }
            _ => {}
        }
    }

    /// Left-arrow: close an open folder, or jump to the parent of anything
    /// else. Two behaviors on one key, which is what makes it feel like
    /// "outwards".
    pub(super) fn collapse_or_parent(&mut self) {
        let Some(row) = self.selected_row().cloned() else {
            return;
        };
        if row.is_dir && row.expanded {
            self.tree.collapse(&row.path);
            self.rebuild_rows();
            return;
        }
        let Some(parent) = row.path.parent() else {
            return;
        };
        if let Some(i) = self.rows.iter().position(|r| r.path == parent) {
            self.select_index(i);
        }
    }

    /// Fold the tree away, or bring it back.
    ///
    /// The keyboard cannot sit in a pane that is not on screen, so folding
    /// moves it to the preview and unfolding puts it back where it was. Press
    /// the key twice and nothing has changed, which is what a toggle should
    /// mean.
    ///
    /// The message names the key from the keymap rather than spelling it out,
    /// because this one is rebindable and a hint that lies is worse than none.
    pub(super) fn toggle_tree_pane(&mut self) {
        let key = self.keymap.spec(Action::ToggleTreePane);
        if self.tree_hidden {
            self.tree_hidden = false;
            // Back to whichever pane had it, so the key is a true toggle.
            self.focus = self.focus_before_hide;
            self.status = format!("tree back — {key} to hide");
        } else {
            self.tree_hidden = true;
            self.focus_before_hide = self.focus;
            self.focus = Focus::Editor;
            self.status = format!("tree hidden — {key} to bring it back");
        }
    }

    /// One step of `Ctrl+Shift+Left` / `Ctrl+Shift+Right`: a narrower or a
    /// wider browser, and the file pane takes whatever it gives up.
    ///
    /// The two ends of the range meet the fold key rather than stopping dead.
    /// Narrowing past the minimum folds the browser away, and widening from
    /// there brings it back — so one pair of keys covers everything from "gone"
    /// to "most of the window", and you never have to remember a second chord
    /// to get out of the corner you just walked into.
    ///
    /// Live only. The width is a view state like the fold, and writing it to
    /// `tiny.conf` on every keypress would make a gesture you use while
    /// reading into a change to your configuration. `*set tree_width 0.4` is
    /// still there for a width you want to keep.
    pub(super) fn resize_tree_pane(&mut self, step: i32) {
        // The source window's left column is the same width, and resized by
        // the same keys — but it cannot be folded away. Folding the browser
        // gives the file the whole screen, which is a thing you want; folding
        // the change list leaves that window with nothing in it.
        if self.window == Window::Source {
            let want = self.config.tree_width + step as f32 * TREE_WIDTH_STEP;
            self.config.tree_width = want.clamp(TREE_WIDTH_MIN, TREE_WIDTH_MAX);
            self.status = format!(
                "changes {}% of the window",
                (self.config.tree_width * 100.0).round()
            );
            return;
        }
        if self.tree_hidden {
            // Nothing to resize while it is folded away; widening is the
            // gesture that asks for it back, and narrowing has nowhere to go.
            if step > 0 {
                self.toggle_tree_pane();
            }
            return;
        }
        let want = self.config.tree_width + step as f32 * TREE_WIDTH_STEP;
        if want < TREE_WIDTH_MIN {
            // Already as narrow as it goes: the next press is asking for it
            // gone, which is what the fold key does.
            self.toggle_tree_pane();
            return;
        }
        self.config.tree_width = want.min(TREE_WIDTH_MAX);
        self.status = format!(
            "browser {}% of the window",
            (self.config.tree_width * 100.0).round()
        );
    }

    /// Put the tree on screen and give it the keyboard. What Esc means from
    /// the preview, whether or not the tree was folded away — "back to the
    /// tree" has to end up at the tree either way.
    pub(super) fn focus_tree(&mut self) {
        self.tree_hidden = false;
        self.focus = Focus::Tree;
    }

    /// `.`: show or hide dotfiles. Writes through to the config so the setting
    /// is consistent with `:set show_hidden`, but does not persist it — that
    /// still needs an explicit save.
    pub(super) fn toggle_hidden(&mut self) {
        let next = !self.tree.show_hidden();
        self.tree.set_show_hidden(next);
        self.config.show_hidden = next;
        self.rebuild_rows();
        self.status = if next {
            "showing hidden files".into()
        } else {
            "hiding hidden files".into()
        };
    }

    /// Re-read the project from disk. The manual replacement for a file
    /// watcher (see `tree`'s module docs). Clean buffers are dropped so they
    /// pick up external changes; dirty ones are kept.
    pub(super) fn refresh(&mut self) {
        self.tree.refresh_all();
        // Drop clean buffers so they re-read from disk; keep unsaved work.
        self.buffers.retain(|_, e| e.dirty);
        self.rebuild_rows();
        self.status = "refreshed".into();
    }

    /// Quit, or ask first if anything is unsaved. The prompt names every dirty
    /// file, since "save changes?" is unanswerable without knowing which.
    ///
    /// The question is asked the way round that makes the safe answer the
    /// obvious one: `y` saves and goes, `n` goes without saving, and Esc stays
    /// here. It used to ask whether to *discard*, where the natural yes threw
    /// work away.
    pub(super) fn request_quit(&mut self) {
        let mut dirty: Vec<String> = self
            .dirty_buffers()
            .iter()
            .map(|p| display_name(p))
            .collect();
        if dirty.is_empty() {
            self.should_quit = true;
            return;
        }
        // The map is unordered, so without this the same two files could be
        // named in either order on successive runs.
        dirty.sort();
        self.mode = Mode::Confirm(Confirm {
            kind: ConfirmKind::QuitUnsaved,
            message: format!(
                "Save changes to {} before quitting?  (y/n, Esc cancels)",
                dirty.join(", ")
            ),
        });
    }

    /// Answering yes to that question: write everything, then leave.
    ///
    /// A failed write cancels the quit. Someone who asked to save on the way
    /// out and is told the save failed has not been given the chance to do
    /// anything about it if the program exits anyway — so tiny stays open with
    /// the failure on the status line, and Ctrl+Q asks again.
    pub(super) fn save_all_and_quit(&mut self) {
        let mut dirty: Vec<PathBuf> = self
            .buffers
            .values()
            .filter(|e| e.dirty)
            .map(|e| e.path.clone())
            .collect();
        dirty.sort();
        let (saved, failed) = self.save_each(&dirty);
        match failed.first() {
            Some(first) => {
                self.status = format!(
                    "saved {saved}, {} failed — {first}; still open",
                    failed.len()
                )
            }
            None => self.should_quit = true,
        }
    }
}

