#[test]
fn copying_a_folder_takes_everything_under_it() {
    let (td, mut app) = fixture();
    fs::create_dir_all(td.path().join("notes/deep/deeper")).unwrap();
    fs::write(td.path().join("notes/deep/deeper/buried.md"), "# buried\n").unwrap();
