//! The project map.
//!
//! What ends up on it, what the filters take off it, where the cursor starts,
//! and what the detail strip says. The geometry of the lines between the boxes
//! is tested in [`crate::ui::ink`] instead, against the grid rather than
//! against a screenshot.

use super::*;

/// The fixture plus the two files it already points at: `design.md` links
/// to `[[architecture]]` and `main.py` calls `utils.load`, so once those
/// exist the map has real edges to draw.
fn linked_fixture_with(cfg: Config) -> (tempfile::TempDir, App) {
    let (td, mut app) = fixture_with(cfg);
    fs::write(
        td.path().join("notes/architecture.md"),
        "# Architecture\n\nback to [[design]]\n",
    )
    .unwrap();
    fs::write(
        td.path().join("src/utils.py"),
        "def load():\n    return 1\n",
    )
    .unwrap();
    command(&mut app, "reload");
    (td, app)
}

fn linked_fixture() -> (tempfile::TempDir, App) {
    linked_fixture_with(Config::default())
}

#[test]
fn the_bottom_bar_says_only_what_is_not_already_on_screen() {
    let (_td, mut app) = fixture();
    let bar = screen(&mut app, 96, 14).pop().expect("a status line");
    assert!(bar.contains("| Ctrl+3 map"), "dividers are pipes:\n{bar}");
    assert!(!bar.contains('·'), "{bar}");
    assert!(
        !bar.contains("F1 help"),
        "the status already opens with `F1 for help`:\n{bar}"
    );
    assert!(
        !bar.contains(": commands"),
        "there is no colon key any more:\n{bar}"
    );
}

#[test]
fn the_map_draws_every_file_in_a_box() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    let out = screen(&mut app, 100, 34).join("\n");
    assert!(out.contains("PROJECT MAP"), "{out}");
    // Names sit inside boxes, so the borders are right beside them.
    assert!(
        out.contains("│design.md│"),
        "a box with a name in it:\n{out}"
    );
    assert!(
        out.contains('╭') && out.contains('╯'),
        "box corners:\n{out}"
    );
}

#[test]
fn the_map_joins_linked_files_with_a_line() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    let out = screen(&mut app, 100, 34).join("\n");
    assert!(out.contains('─') || out.contains('│'), "lines:\n{out}");
    // Only the arrow glyphs: the ascii set is `< > ^ v`, which are letters
    // anywhere else on the screen. That the routing writes no glyph at all,
    // in either set, is `ink`'s own test.
    assert!(
        !['◂', '▸', '▴', '▾'].iter().any(|a| out.contains(*a)),
        "a connection is a plain line — which way it runs is in the strip below:\n{out}"
    );
}

#[test]
fn a_code_file_that_calls_another_is_joined_to_it() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    // Only calls: the notes are switched off, so whatever is left on
    // screen is there because of the code.
    app.on_key(ch('1'));
    app.on_key(ch('2'));
    let out = screen(&mut app, 100, 34).join("\n");
    assert!(out.contains("│main.py│"), "{out}");
    assert!(out.contains("│utils.py│"), "{out}");
    assert!(
        out.contains("unconnected"),
        "the notes are unconnected now, so they are filed as such:\n{out}"
    );
}

#[test]
fn the_map_draws_the_cursors_connections_and_nobody_elses() {
    let (td, mut app) = linked_fixture();
    // A file joined to nothing, so there is a selection with no lines.
    fs::write(td.path().join("lonely.md"), "nothing points here\n").unwrap();
    command(&mut app, "reload");
    open_map(&mut app);

    // Every cell a line can occupy. The same boxes are drawn either way, so
    // the difference between two frames is exactly the connections in them.
    let ink = |app: &mut App| -> usize {
        screen(app, 100, 34)
            .join("")
            .chars()
            .filter(|c| "─│┌┐└┘├┤┬┴┼".contains(*c))
            .count()
    };
    let connected = ink(&mut app);

    // Walk to the lonely file. It is under its own heading at the end.
    for _ in 0..12 {
        app.on_key(k(KeyCode::Tab));
        let map = app.project_map.as_ref().expect("the map is open");
        if map
            .selected_node()
            .is_some_and(|n| n.rel.ends_with("lonely.md"))
        {
            break;
        }
    }
    let map = app.project_map.as_ref().expect("the map is open");
    assert!(
        map.selected_node()
            .is_some_and(|n| n.rel.ends_with("lonely.md")),
        "Tab should have reached it"
    );
    let out = screen(&mut app, 100, 34).join("\n");
    assert!(
        out.contains("│lonely.md│"),
        "it is still drawn, under its own heading:\n{out}"
    );
    assert!(
        ink(&mut app) < connected,
        "and nothing is joined to it, so its lines are gone:\n{out}"
    );
}

#[test]
fn nothing_is_drawn_on_top_of_a_box() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    let rows = screen(&mut app, 100, 34);
    // Every name on screen is whole, with its own border either side: a
    // line crossing the box would have overwritten one of those cells.
    for name in ["design.md", "architecture.md", "main.py", "utils.py"] {
        let row = rows
            .iter()
            .find(|r| r.contains(name))
            .unwrap_or_else(|| panic!("{name} is missing:\n{}", rows.join("\n")));
        let at = row.find(name).unwrap();
        assert_eq!(
            row[..at].chars().last().unwrap(),
            '│',
            "{name} sits inside its box:\n{row}"
        );
    }
}

/// Everything on screen drawn in one color, row by row.
///
/// The map is the only place tiny uses color at all, so a color is a
/// reliable way to ask "which files did it call outgoing" without knowing
/// where on the grid they landed.
fn drawn_in(app: &mut App, color: Color) -> String {
    let mut t = Terminal::new(TestBackend::new(100, 34)).unwrap();
    t.draw(|f| crate::ui::draw(f, app)).unwrap();
    let buf = t.backend().buffer().clone();
    let mut out = String::new();
    for y in 0..buf.area.height {
        for x in 0..buf.area.width {
            match buf.cell((x, y)) {
                Some(c) if c.fg == color => out.push_str(c.symbol()),
                _ => {}
            }
        }
        out.push('\n');
    }
    out
}

/// Put the map's cursor on a named file without walking there.
fn cursor_on(app: &mut App, name: &str) {
    let map = app.project_map.as_mut().expect("the map is open");
    map.selected = map
        .graph
        .nodes
        .iter()
        .position(|n| n.rel.ends_with(name))
        .unwrap_or_else(|| panic!("no node for {name}"));
}

#[test]
fn a_file_this_one_reaches_is_drawn_in_the_outgoing_color() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    // `main.py` calls `utils.load`, and nothing calls `main.py`.
    cursor_on(&mut app, "main.py");

    let red = drawn_in(&mut app, Color::Red);
    assert!(red.contains("utils.py"), "the file it reaches:\n{red}");
    assert!(red.contains("out:"), "and the row that names them:\n{red}");

    let green = drawn_in(&mut app, Color::Green);
    assert!(
        !green.contains("utils.py"),
        "the connection runs one way, so it is not both:\n{green}"
    );
}

#[test]
fn a_file_that_reaches_this_one_is_drawn_in_the_incoming_color() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    cursor_on(&mut app, "utils.py");

    let green = drawn_in(&mut app, Color::Green);
    assert!(
        green.contains("main.py"),
        "the file that reaches it:\n{green}"
    );
    assert!(
        green.contains("in:"),
        "and the row that names them:\n{green}"
    );

    let red = drawn_in(&mut app, Color::Red);
    assert!(!red.contains("main.py"), "not the other way:\n{red}");
}

#[test]
fn a_file_on_neither_side_of_the_cursor_is_left_uncolored() {
    let (_td, mut app) = linked_fixture();
    open_map(&mut app);
    cursor_on(&mut app, "main.py");
    for color in [Color::Red, Color::Green] {
        let painted = drawn_in(&mut app, color);
        assert!(
            !painted.contains("design.md"),
            "design.md has nothing to do with main.py:\n{painted}"
        );
    }
}

#[test]
fn the_two_directions_can_be_recolored_from_the_config() {
    let (_td, mut app) = linked_fixture();
    command(&mut app, "set theme.map_out #ff00aa");
    command(&mut app, "set theme.map_in #00ccff");
    open_map(&mut app);
    cursor_on(&mut app, "utils.py");

    let hex = drawn_in(&mut app, Color::Rgb(0x00, 0xcc, 0xff));
    assert!(hex.contains("main.py"), "the incoming color took:\n{hex}");
    assert!(
        drawn_in(&mut app, Color::Green).trim().is_empty(),
        "and the shipped green is gone"
    );

    cursor_on(&mut app, "main.py");
    let hex = drawn_in(&mut app, Color::Rgb(0xff, 0x00, 0xaa));
    assert!(
        hex.contains("utils.py"),
        "and so did the outgoing one:\n{hex}"
    );
}

#[test]
fn the_map_can_be_drawn_without_box_characters() {
    let cfg = Config {
        markers: Markers::Ascii,
        ..Config::default()
    };
    let (_td, mut app) = linked_fixture_with(cfg);
    open_map(&mut app);
    let out = screen(&mut app, 100, 34).join("\n");
    assert!(!out.contains('╭'), "no box drawing at all:\n{out}");
    assert!(
        out.contains("|design.md|"),
        "boxes are made of pipes:\n{out}"
    );
    assert!(out.contains('+'), "and corners of plus signs:\n{out}");
}

files.src/app/tests/mod.rs:
//! The fixtures every test here shares, and the tests themselves.
//!
//! One project on a temp directory with one of each thing the panes have to
//! handle — a folder, a markdown note, a source file, a picture that will not
//! decode — plus the helpers that drive an `App` without a terminal: [`screen`]
//! renders a frame into strings, [`select`] puts the cursor on a named row,
//! and [`k`] / [`ch`] / [`ctrl`] build key events.
//!
//! Tests assert on the drawn screen wherever they can. Checking that
//! `app.selected == 3` proves a field changed; checking that the name is on
//! the screen proves the user can see it, which is the thing that was actually
//! promised.

pub(super) use super::*;
pub(super) use crate::app::mode::*;
pub(super) use crate::app::parts::*;
pub(super) use crate::app::preview::*;
pub(super) use crate::config::keys::Action;
pub(super) use crate::config::{Markers, Position, Side};
pub(super) use crossterm::event::KeyEventKind;
pub(super) use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
pub(super) use ratatui::Terminal;
pub(super) use ratatui::backend::TestBackend;
pub(super) use ratatui::style::{Color, Modifier};
pub(super) use std::fs;
pub(super) use std::path::{Path, PathBuf};

mod commands;
mod editing;
mod fileops;
mod layout;
mod map;
mod navigation;
mod preview;
mod scrolling;
mod search;
mod settings;
mod single_file;
mod source;
mod watch;

/// A small project with one of each thing the panes have to handle.
pub(super) fn build(dir: &Path) {
    fs::create_dir_all(dir.join("notes")).unwrap();
    fs::create_dir_all(dir.join("src")).unwrap();
    fs::write(
        dir.join("notes/design.md"),
        "# Design Notes\n\nThe core idea is a split view. See [[architecture]].\n\n- one\n- two\n",
    )
    .unwrap();
    fs::write(
        dir.join("src/main.py"),
        "import utils\n\n\ndef main():\n    return utils.load()\n",
    )
    .unwrap();
    fs::write(dir.join("README.md"), "# Fixture\n\nhello widget\n").unwrap();
    fs::write(dir.join("logo.png"), [0x89u8, b'P', b'N', b'G', 0, 1, 2, 3]).unwrap();
}

pub(super) fn target(root: &Path, file: Option<PathBuf>) -> project::Target {
    project::Target {
        root: root.to_path_buf(),
        file,
        created: false,
    }
}

pub(super) fn fixture() -> (tempfile::TempDir, App) {
    fixture_with(Config::default())
}

pub(super) fn fixture_with(cfg: Config) -> (tempfile::TempDir, App) {
    let td = tempfile::tempdir().unwrap();
    build(td.path());
    let app = App::new(target(td.path(), None), cfg, None).unwrap();
    (td, app)
}

pub(super) fn screen(app: &mut App, w: u16, h: u16) -> Vec<String> {
    let mut t = Terminal::new(TestBackend::new(w, h)).unwrap();
    t.draw(|f| crate::ui::draw(f, app)).unwrap();
    let buf = t.backend().buffer().clone();
    (0..buf.area.height)
        .map(|y| {
            (0..buf.area.width)
                .map(|x| buf.cell((x, y)).map(|c| c.symbol()).unwrap_or(" "))
                .collect::<String>()
        })
        .collect()
}

pub(super) fn joined(app: &mut App) -> String {
    screen(app, 90, 24).join("\n")
}

/// Text drawn reversed, split by where it is on screen: the dropped-down
/// result list, and the preview pane below it.
///
/// Kept apart because both mark their matches, and counting them together
/// would let either one pass for both. The list spans the full width and sits
/// above the panes, so the split is by row, not by column: its bottom border
/// is the first `└` down the left edge, and everything under that belongs to
/// the panes. With no search open there is no list, and the whole screen below
/// the browser's columns is the preview.
pub(super) fn marked_by_pane(app: &mut App, w: u16, h: u16) -> (String, String) {
    let searching = matches!(&app.mode, Mode::Bar(b) if !b.is_command());
    let mut t = Terminal::new(TestBackend::new(w, h)).unwrap();
    t.draw(|f| crate::ui::draw(f, app)).unwrap();
    let buf = t.backend().buffer().clone();
    let read = |rows: std::ops::Range<u16>, cols: std::ops::Range<u16>| -> String {
        let mut out = String::new();
        for y in rows {
            for x in cols.clone() {
                match buf.cell((x, y)) {
                    Some(c) if c.modifier.contains(Modifier::REVERSED) => out.push_str(c.symbol()),
                    _ => {}
                }
            }
        }
        out
    };
    let split = if searching {
        (0..buf.area.height)
            .find(|y| buf.cell((0, *y)).is_some_and(|c| c.symbol() == "└"))
            .map_or(0, |y| y + 1)
    } else {
        0
    };
    // The side pane is `tree_width` of the window; a couple of columns of
    // slack covers its border either way.
    let panes_split = (w as f32 * Config::default().tree_width) as u16 + 2;
    (
        read(0..split, 0..buf.area.width),
        read(split..buf.area.height, panes_split..buf.area.width),
    )
}

/// Just the preview pane's marks.
pub(super) fn marked_in_preview(app: &mut App, w: u16, h: u16) -> String {
    marked_by_pane(app, w, h).1
}

pub(super) fn type_search(app: &mut App, query: &str) {
    app.on_key(ch('/'));
    for c in query.chars() {
        app.on_key(ch(c));
    }
}

pub(super) fn k(code: KeyCode) -> KeyEvent {
    KeyEvent {
        code,
        modifiers: KeyModifiers::NONE,
        kind: KeyEventKind::Press,
        state: crossterm::event::KeyEventState::NONE,
    }
}

pub(super) fn ch(c: char) -> KeyEvent {
    k(KeyCode::Char(c))
}

pub(super) fn shift(code: KeyCode) -> KeyEvent {
    KeyEvent {
        modifiers: KeyModifiers::SHIFT,
        ..k(code)
    }
}

pub(super) fn ctrl(c: char) -> KeyEvent {
    ctrl_key(KeyCode::Char(c))
}

pub(super) fn ctrl_shift(code: KeyCode) -> KeyEvent {
    KeyEvent {
        modifiers: KeyModifiers::CONTROL | KeyModifiers::SHIFT,
        ..k(code)
    }
}

pub(super) fn ctrl_alt(code: KeyCode) -> KeyEvent {
    KeyEvent {
        modifiers: KeyModifiers::CONTROL | KeyModifiers::ALT,
        ..k(code)
    }
}

pub(super) fn alt(code: KeyCode) -> KeyEvent {
    KeyEvent {
        modifiers: KeyModifiers::ALT,
        ..k(code)
    }
}

pub(super) fn ctrl_key(code: KeyCode) -> KeyEvent {
    KeyEvent {
        modifiers: KeyModifiers::CONTROL,
        ..k(code)
    }
}

pub(super) fn type_str(app: &mut App, s: &str) {
    for c in s.chars() {
        app.on_key(ch(c));
    }
}

/// Run a command line through the bar, exactly as a user would.
/// Run a command from wherever the keyboard happens to be.
///
/// Ctrl+P rather than `:`, because in the editor a colon is a colon — the
/// same reason the binding exists at all.
pub(super) fn command(app: &mut App, line: &str) {
    app.on_key(ctrl('p'));
    type_str(app, line);
    app.on_key(k(KeyCode::Enter));
}

/// Type `line` into the command bar, press Tab, and give back what the bar
/// holds afterwards.
pub(super) fn completed(app: &mut App, line: &str) -> String {
    app.on_key(ctrl('p'));
    type_str(app, line);
    app.on_key(k(KeyCode::Tab));
    let Mode::Bar(b) = &app.mode else {
        panic!("the bar closed")
    };
    let out = b.command().to_string();
    app.on_key(k(KeyCode::Esc));
    out
}

/// Whether two paths name the same file, allowing for the ways an operating
/// system spells one.
///
/// A test that builds a path from the temp directory and compares it with one
/// that came back from `git` is comparing two spellings of the same file. On
/// macOS the temp directory lives under `/var`, which is a symlink to
/// `/private/var`, so git's answer and the test's differ by a directory nobody
/// typed. Windows has it the other way round: canonicalizing adds a `\\?\`
/// prefix that a plain path does not have, so resolving *both* is the only
/// comparison that holds everywhere.
pub(super) fn same_file(a: &Path, b: &Path) -> bool {
    if a == b {
        return true;
    }
    match (a.canonicalize(), b.canonicalize()) {
        (Ok(a), Ok(b)) => a == b,
        _ => false,
    }
}

/// Open the settings area. A command now, not a key — see `config::keys`.
pub(super) fn settings(app: &mut App) {
    command(app, "config");
}

/// Switch to the map window, the way `Ctrl+3` does.
pub(super) fn open_map(app: &mut App) {
    app.on_key(ctrl('3'));
}

pub(super) fn select(app: &mut App, name: &str) {
    for _ in 0..12 {
        let paths: Vec<PathBuf> = app
            .rows
            .iter()
            .filter(|r| r.is_dir && !r.expanded)
            .map(|r| r.path.clone())
            .collect();
        if paths.is_empty() {
            break;
        }
        for p in paths {
            app.tree.expand(&p);
        }
        app.rows = app.tree.flatten();
    }
    // Expanding read those folders; stamp them the way the real navigation
    // keys would, so the disk watcher has something to compare against.
    app.note_dirs();
    let i = app
        .rows
        .iter()
        .position(|r| r.name == name)
        .unwrap_or_else(|| {
            panic!(
                "no row named {name} in {:?}",
                app.rows.iter().map(|r| &r.name).collect::<Vec<_>>()
            )
        });
    app.selected = i;
    app.sync_preview();
}

/// Open the keybinds window with the cursor on `action`.
pub(super) fn keybinds_on(app: &mut App, action: Action) {
    settings(app);
    app.on_key(k(KeyCode::Enter)); // the Keybinds button is the first row
    let rows = Action::all().position(|a| a == action).unwrap() + KEYBIND_BUTTONS.len();
    for _ in 0..rows {
        app.on_key(k(KeyCode::Down));
    }
}

