    type_str(&mut app, "e");
    let rows = screen(&mut app, 90, 24);
    let Mode::Bar(b) = &app.mode else {
        panic!("bar closed")
    };
    assert!(b.results.len() > 8, "a short list proves nothing");

    let bottom = rows
        .iter()
        .position(|r| r.starts_with('└'))
        .expect("the list is a closed box");
    assert!(
        bottom < 9,
        "it stops at a third of the window:\n{}",
        rows.join("\n")
    );
}

