    assert_eq!(
        app.selected_path().unwrap(),
        paths[0],
        "starts on the first"
    );

    // Walk down to the first result in a different file.
    let other = paths
        .iter()
        .position(|p| *p != paths[0])
        .expect("fixture should match in more than one file");
    for _ in 0..other {
