//! Pixel dimensions, read straight out of a file header.
//!
//! Every image format writes its size within the first few dozen bytes, in a
//! fixed place, in a documented layout. So tiny reads those bytes and stops.
//!
//! # Why not a decoder
//!
//! This used to go through the `image` crate, which is an excellent decoder
//! and brings twenty-odd crates with it — PNG, JPEG, GIF, WebP and TIFF
//! decoders, two inflate implementations, a color-management library. That is
//! the right dependency for a program that draws pictures. tiny stopped
//! drawing pictures (see the [`super`] module docs), and what is left is
//! reading two integers.
//!
//! # Failure is a missing line, not an error
//!
//! Every read here is bounds-checked and every parse returns `Option`, so a
//! truncated file, a format that is not really the one the extension claims,
//! or a layout this does not know about all end the same way: no resolution in
//! the pane, and a note saying so. Nothing here can panic on hostile input,
//! and nothing here needs to be right for the rest of the preview to work.
//!
//! # I/O is a few reads, not a slurp
//!
//! [`read`] seeks to what it needs. Most formats are answered by the first 32
//! bytes; JPEG walks its segment chain because a big EXIF block can sit in
//! front of the frame header, and TIFF follows one offset to its directory.
//! Nothing reads the pixels.

use std::fs::File;
use std::io::{Read, Seek, SeekFrom};
use std::path::Path;

use anyhow::{Context, Result, anyhow};

/// A JPEG whose frame header is not within this many bytes of the start is
/// treated as unreadable. Real files put it within a few hundred; the cap is
/// what stops a corrupt or hostile file from walking us through gigabytes of
/// invented segment lengths.
const MAX_JPEG_SCAN: u64 = 4 * 1024 * 1024;

/// The dimensions of the image in `path`, from its header alone.
///
/// The format is identified by its magic bytes, not by the file's extension,
/// so a PNG saved as `.jpg` still reports its true size.
pub(super) fn read(path: &Path) -> Result<(u32, u32)> {
    let mut file = File::open(path).with_context(|| format!("cannot read {}", name(path)))?;
    let head = at(&mut file, 0, 32)?;
    let unknown = || anyhow!("{} is not an image tiny can measure", name(path));

    let size = match () {
        _ if head.starts_with(b"\x89PNG\r\n\x1a\n") => png(&head),
        _ if head.starts_with(b"GIF87a") || head.starts_with(b"GIF89a") => gif(&head),
        _ if head.starts_with(b"BM") => bmp(&head),
        _ if head.starts_with(b"\xff\xd8") => jpeg(&mut file)?,
        _ if head.starts_with(b"RIFF") && head.get(8..12) == Some(b"WEBP") => webp(&mut file)?,
        _ if head.starts_with(b"II\x2a\x00") || head.starts_with(b"MM\x00\x2a") => {
            tiff(&mut file, &head)?
        }
        _ if head.starts_with(b"\x00\x00\x01\x00") => ico(&head),
        _ => return Err(unknown()),
    };
    // A zero dimension is a corrupt header, not a zero-sized picture.
    size.filter(|&(w, h)| w > 0 && h > 0)
        .ok_or_else(|| anyhow!("the header of {} is damaged", name(path)))
}

/// `len` bytes from `off`. A short read is not an error — it comes back short,
/// and the parser that asked for it fails its own bounds check.
fn at(file: &mut File, off: u64, len: usize) -> Result<Vec<u8>> {
    file.seek(SeekFrom::Start(off))?;
    let mut buf = vec![0u8; len];
    let mut filled = 0;
    while filled < len {
        match file.read(&mut buf[filled..])? {
            0 => break,
            n => filled += n,
        }
    }
    buf.truncate(filled);
    Ok(buf)
}

// ---- the formats ----------------------------------------------------------

/// IHDR is always the first chunk, so the size is at a fixed offset.
fn png(b: &[u8]) -> Option<(u32, u32)> {
    (b.get(12..16)? == b"IHDR").then_some(())?;
    Some((be32(b, 16)?, be32(b, 20)?))
}

/// The logical screen descriptor, immediately after the six-byte signature.
fn gif(b: &[u8]) -> Option<(u32, u32)> {
    Some((le16(b, 6)? as u32, le16(b, 8)? as u32))
}

/// The BITMAPINFOHEADER. Height is signed: negative means the rows are stored
/// top-down, which says nothing about how tall the picture is.
fn bmp(b: &[u8]) -> Option<(u32, u32)> {
    let w = le32(b, 18)? as i32;
    let h = le32(b, 22)? as i32;
    Some((w.unsigned_abs(), h.unsigned_abs()))
}

/// The first entry of the directory. A dimension of 0 means 256 — the field is
/// one byte and 256 does not fit in it.
fn ico(b: &[u8]) -> Option<(u32, u32)> {
    let byte = |i: usize| {
        b.get(i)
            .copied()
            .map(|v| if v == 0 { 256 } else { v as u32 })
    };
    Some((byte(6)?, byte(7)?))
}

/// Walk the segment chain to the frame header.
///
/// JPEG puts the size in a start-of-frame segment, and there is no telling how
/// far in that is: EXIF, ICC profiles and embedded thumbnails all come first
/// and can be tens of kilobytes each. So the segments are stepped through by
/// their declared lengths until a start-of-frame turns up.
///
/// The `0xC4`, `0xC8` and `0xCC` exclusions matter: those three markers sit in
/// the middle of the start-of-frame range but mean something else entirely
/// (Huffman tables, an extension, arithmetic coding), and reading a size out
/// of one gives a confident wrong answer.
fn jpeg(file: &mut File) -> Result<Option<(u32, u32)>> {
    let mut pos = 2u64;
    while pos < MAX_JPEG_SCAN {
        let header = at(file, pos, 4)?;
        let [mut lead, mut marker] = [*header.first().unwrap_or(&0), *header.get(1).unwrap_or(&0)];
        if lead != 0xFF {
            return Ok(None);
        }
        // Any number of 0xFF bytes may pad the gap before a marker.
        let mut skipped = 0u64;
        while marker == 0xFF {
            skipped += 1;
            let next = at(file, pos + 1 + skipped, 2)?;
            lead = 0xFF;
            marker = *next.first().unwrap_or(&0);
        }
        let _ = lead;
        pos += 2 + skipped;
        match marker {
            // Start of frame, in every one of its flavors.
            0xC0..=0xCF if !matches!(marker, 0xC4 | 0xC8 | 0xCC) => {
                let seg = at(file, pos, 9)?;
                // Two bytes of length, a byte of precision, then height —
                // JPEG is the one format here that writes it that way round.
                return Ok(match (be16(&seg, 5), be16(&seg, 3)) {
                    (Some(w), Some(h)) => Some((w as u32, h as u32)),
                    _ => None,
                });
            }
            // Standalone markers: no length field to skip.
            0x01 | 0xD0..=0xD7 => {}
            // Start of scan or end of image: the header is over.
            0xDA | 0xD9 => return Ok(None),
            _ => {
                let seg = at(file, pos, 2)?;
                let len = match be16(&seg, 0) {
                    // A length below 2 does not include its own field, so it
                    // cannot be right and stepping by it would not terminate.
                    Some(n) if n >= 2 => n as u64,
                    _ => return Ok(None),
                };
                pos += len;
            }
        }
    }
    Ok(None)
}

/// One of three sub-formats, told apart by the first chunk's identifier.
///
/// All three store the dimensions minus one, because a WebP cannot be zero
/// pixels wide and spending a code point on saying so would be wasteful.
fn webp(file: &mut File) -> Result<Option<(u32, u32)>> {
    let b = at(file, 12, 18)?;
    let Some(tag) = b.get(0..4) else {
        return Ok(None);
    };
    Ok(match tag {
        // Extended: an explicit canvas size, 24 bits each.
        b"VP8X" => match (le24(&b, 12), le24(&b, 15)) {
            (Some(w), Some(h)) => Some((w + 1, h + 1)),
            _ => None,
        },
        // Lossless: 14 bits each, packed after a one-byte signature.
        b"VP8L" => match le32(&b, 9) {
            Some(bits) if b.get(8) == Some(&0x2F) => {
                Some(((bits & 0x3FFF) + 1, ((bits >> 14) & 0x3FFF) + 1))
            }
            _ => None,
        },
        // Lossy: the VP8 keyframe header, behind its start code.
        b"VP8 " => match (le16(&b, 14), le16(&b, 16)) {
            (Some(w), Some(h)) if b.get(11..14) == Some(&[0x9D, 0x01, 0x2A][..]) => {
                Some(((w & 0x3FFF) as u32, (h & 0x3FFF) as u32))
            }
            _ => None,
        },
        _ => None,
    })
}

/// Follow the offset to the first image file directory and look for the two
/// size tags in it.
///
/// TIFF is the only one of these that is genuinely a database rather than a
/// header: the fields are tagged, unordered, and live wherever an offset says.
/// Both byte orders are in the wild, which is what the magic bytes announce.
fn tiff(file: &mut File, head: &[u8]) -> Result<Option<(u32, u32)>> {
    let big_endian = head.starts_with(b"MM");
    let u16at = |b: &[u8], i: usize| {
        if big_endian { be16(b, i) } else { le16(b, i) }
    };
    let u32at = |b: &[u8], i: usize| {
        if big_endian { be32(b, i) } else { le32(b, i) }
    };

    let Some(ifd) = u32at(head, 4) else {
        return Ok(None);
    };
    let count_bytes = at(file, ifd as u64, 2)?;
    let Some(count) = u16at(&count_bytes, 0) else {
        return Ok(None);
    };
    // Twelve bytes per entry. A directory claiming thousands of them is
    // corrupt, and reading it would be a large allocation on a hover.
    let entries = at(file, ifd as u64 + 2, count.min(512) as usize * 12)?;

    let (mut width, mut height) = (None, None);
    for e in entries.as_chunks::<12>().0 {
        let (Some(tag), Some(kind)) = (u16at(e, 0), u16at(e, 2)) else {
            continue;
        };
        // The value sits inline when it fits in four bytes, which both a SHORT
        // and a LONG always do.
        let value = match kind {
            3 => u16at(e, 8).map(u32::from), // SHORT
            4 => u32at(e, 8),                // LONG
            _ => None,
        };
        match tag {
            256 => width = value,
            257 => height = value,
            _ => {}
        }
        if let (Some(w), Some(h)) = (width, height) {
            return Ok(Some((w, h)));
        }
    }
    Ok(None)
}

// ---- reading numbers out of bytes -----------------------------------------

fn be16(b: &[u8], i: usize) -> Option<u16> {
    Some(u16::from_be_bytes(b.get(i..i + 2)?.try_into().ok()?))
}

fn le16(b: &[u8], i: usize) -> Option<u16> {
    Some(u16::from_le_bytes(b.get(i..i + 2)?.try_into().ok()?))
}

fn be32(b: &[u8], i: usize) -> Option<u32> {
    Some(u32::from_be_bytes(b.get(i..i + 4)?.try_into().ok()?))
}

fn le32(b: &[u8], i: usize) -> Option<u32> {
    Some(u32::from_le_bytes(b.get(i..i + 4)?.try_into().ok()?))
}

/// A 24-bit little-endian integer, which only WebP uses.
fn le24(b: &[u8], i: usize) -> Option<u32> {
    let s = b.get(i..i + 3)?;
    Some(u32::from(s[0]) | u32::from(s[1]) << 8 | u32::from(s[2]) << 16)
}

/// The file name, for messages. Falls back to the whole path.
fn name(path: &Path) -> String {
    path.file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_else(|| path.display().to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    /// Write bytes to a file and measure them. Only the header has to be
    /// real — nothing here decodes anything, so there are no pixels to
    /// provide and the fixtures can be written by hand.
    fn measure(dir: &tempfile::TempDir, name: &str, bytes: &[u8]) -> Result<(u32, u32)> {
        let p: PathBuf = dir.path().join(name);
        std::fs::write(&p, bytes).unwrap();
        read(&p)
    }

    fn png_bytes(w: u32, h: u32) -> Vec<u8> {
        let mut v = b"\x89PNG\r\n\x1a\n".to_vec();
        v.extend_from_slice(&13u32.to_be_bytes()); // IHDR length
        v.extend_from_slice(b"IHDR");
        v.extend_from_slice(&w.to_be_bytes());
        v.extend_from_slice(&h.to_be_bytes());
        v.extend_from_slice(&[8, 6, 0, 0, 0]); // depth, color, the rest
        v
    }

    #[test]
    fn a_png_reports_its_size() {
        let td = tempfile::tempdir().unwrap();
        assert_eq!(
            measure(&td, "a.png", &png_bytes(1920, 1080)).unwrap(),
            (1920, 1080)
        );
    }

    #[test]
    fn the_format_comes_from_the_bytes_not_the_name() {
        // A PNG wearing a .jpg suffix still measures as a PNG.
        let td = tempfile::tempdir().unwrap();
        assert_eq!(
            measure(&td, "liar.jpg", &png_bytes(33, 17)).unwrap(),
            (33, 17)
        );
    }

    #[test]
    fn a_gif_reports_its_size() {
        let td = tempfile::tempdir().unwrap();
        let mut v = b"GIF89a".to_vec();
        v.extend_from_slice(&640u16.to_le_bytes());
        v.extend_from_slice(&480u16.to_le_bytes());
        v.extend_from_slice(&[0; 8]);
        assert_eq!(measure(&td, "a.gif", &v).unwrap(), (640, 480));
    }

    #[test]
    fn a_bitmap_is_as_tall_as_it_is_however_its_rows_are_stored() {
        let td = tempfile::tempdir().unwrap();
        let bmp = |h: i32| {
            let mut v = b"BM".to_vec();
            v.extend_from_slice(&[0; 16]); // file header, then the info header size
            v.extend_from_slice(&100i32.to_le_bytes());
            v.extend_from_slice(&h.to_le_bytes());
            v.extend_from_slice(&[0; 8]);
            v
        };
        assert_eq!(measure(&td, "up.bmp", &bmp(50)).unwrap(), (100, 50));
        // A negative height means top-down rows, not a negative picture.
        assert_eq!(measure(&td, "down.bmp", &bmp(-50)).unwrap(), (100, 50));
    }

    #[test]
    fn an_icon_of_no_stated_size_is_the_one_size_that_does_not_fit() {
        let td = tempfile::tempdir().unwrap();
        let ico = |w: u8, h: u8| {
            let mut v = vec![0, 0, 1, 0, 1, 0];
            v.extend_from_slice(&[w, h, 0, 0, 1, 0, 32, 0]);
            v.extend_from_slice(&[0; 16]);
            v
        };
        assert_eq!(measure(&td, "small.ico", &ico(48, 48)).unwrap(), (48, 48));
        assert_eq!(measure(&td, "big.ico", &ico(0, 0)).unwrap(), (256, 256));
    }

    /// A JPEG with `pad` bytes of segments in front of the frame header, so
    /// the walk has something to walk.
    fn jpeg_bytes(w: u16, h: u16, pad: usize) -> Vec<u8> {
        let mut v = vec![0xFF, 0xD8];
        if pad > 0 {
            v.extend_from_slice(&[0xFF, 0xE1]); // APP1, where EXIF lives
            v.extend_from_slice(&((pad + 2) as u16).to_be_bytes());
            v.extend(std::iter::repeat_n(0u8, pad));
        }
        v.extend_from_slice(&[0xFF, 0xC0]); // SOF0
        v.extend_from_slice(&11u16.to_be_bytes());
        v.push(8); // precision
        v.extend_from_slice(&h.to_be_bytes());
        v.extend_from_slice(&w.to_be_bytes());
        v.extend_from_slice(&[3, 1, 0x11, 0]);
        v
    }

    #[test]
    fn a_jpeg_reports_its_size_however_much_metadata_is_in_front_of_it() {
        let td = tempfile::tempdir().unwrap();
        assert_eq!(
            measure(&td, "bare.jpg", &jpeg_bytes(800, 600, 0)).unwrap(),
            (800, 600)
        );
        // A camera's EXIF block with a thumbnail in it is easily this big.
        assert_eq!(
            measure(&td, "exif.jpg", &jpeg_bytes(4032, 3024, 60_000)).unwrap(),
            (4032, 3024)
        );
    }

    #[test]
    fn a_jpeg_huffman_table_is_not_mistaken_for_a_frame_header() {
        // 0xC4 sits inside the start-of-frame marker range but is a Huffman
        // table. Reading a size out of it would give a confident wrong answer.
        let td = tempfile::tempdir().unwrap();
        let mut v = vec![0xFF, 0xD8, 0xFF, 0xC4];
        v.extend_from_slice(&20u16.to_be_bytes());
        v.extend_from_slice(&[0xAB; 18]);
        v.extend_from_slice(&jpeg_bytes(320, 240, 0)[2..]);
        assert_eq!(measure(&td, "huff.jpg", &v).unwrap(), (320, 240));
    }

    fn webp_bytes(chunk: &[u8; 4], payload: &[u8]) -> Vec<u8> {
        let mut v = b"RIFF".to_vec();
        v.extend_from_slice(&((payload.len() + 12) as u32).to_le_bytes());
        v.extend_from_slice(b"WEBP");
        v.extend_from_slice(chunk);
        v.extend_from_slice(&(payload.len() as u32).to_le_bytes());
        v.extend_from_slice(payload);
        v
    }

    #[test]
    fn all_three_kinds_of_webp_report_their_size() {
        let td = tempfile::tempdir().unwrap();

        // Extended: an explicit canvas, stored minus one.
        let mut x = vec![0u8; 10];
        x[4..7].copy_from_slice(&(1919u32.to_le_bytes()[..3]));
        x[7..10].copy_from_slice(&(1079u32.to_le_bytes()[..3]));
        assert_eq!(
            measure(&td, "x.webp", &webp_bytes(b"VP8X", &x)).unwrap(),
            (1920, 1080)
        );

        // Lossless: 14 bits each, packed behind a signature byte.
        let bits = (639u32) | (479u32 << 14);
        let mut l = vec![0x2F];
        l.extend_from_slice(&bits.to_le_bytes());
        assert_eq!(
            measure(&td, "l.webp", &webp_bytes(b"VP8L", &l)).unwrap(),
            (640, 480)
        );

        // Lossy: the VP8 keyframe header, behind its start code.
        let mut y = vec![0u8; 3];
        y.extend_from_slice(&[0x9D, 0x01, 0x2A]);
        y.extend_from_slice(&300u16.to_le_bytes());
        y.extend_from_slice(&200u16.to_le_bytes());
        assert_eq!(
            measure(&td, "y.webp", &webp_bytes(b"VP8 ", &y)).unwrap(),
            (300, 200)
        );
    }

    /// A one-directory TIFF holding just the two size tags.
    fn tiff_bytes(w: u32, h: u32, big_endian: bool) -> Vec<u8> {
        let u16b = |v: u16| {
            if big_endian {
                v.to_be_bytes()
            } else {
                v.to_le_bytes()
            }
        };
        let u32b = |v: u32| {
            if big_endian {
                v.to_be_bytes()
            } else {
                v.to_le_bytes()
            }
        };
        let mut v = if big_endian {
            b"MM\x00\x2a".to_vec()
        } else {
            b"II\x2a\x00".to_vec()
        };
        v.extend_from_slice(&u32b(8)); // the directory starts right after
        v.extend_from_slice(&u16b(2)); // two entries
        for (tag, value) in [(256u16, w), (257, h)] {
            v.extend_from_slice(&u16b(tag));
            v.extend_from_slice(&u16b(4)); // LONG
            v.extend_from_slice(&u32b(1)); // one of them
            v.extend_from_slice(&u32b(value));
        }
        v.extend_from_slice(&u32b(0)); // no next directory
        v
    }

    #[test]
    fn a_tiff_reports_its_size_in_either_byte_order() {
        let td = tempfile::tempdir().unwrap();
        assert_eq!(
            measure(&td, "le.tif", &tiff_bytes(2048, 1536, false)).unwrap(),
            (2048, 1536)
        );
        assert_eq!(
            measure(&td, "be.tif", &tiff_bytes(2048, 1536, true)).unwrap(),
            (2048, 1536)
        );
    }

    #[test]
    fn nothing_hostile_gets_further_than_a_message() {
        let td = tempfile::tempdir().unwrap();
        let cases: &[(&str, Vec<u8>)] = &[
            ("empty.png", Vec::new()),
            ("text.png", b"this is not a png".to_vec()),
            // A truncated header: the magic is right and the size is not there.
            ("cut.png", png_bytes(10, 10)[..18].to_vec()),
            // A zero dimension is a damaged header, not a zero-sized picture.
            ("zero.png", png_bytes(0, 100)),
            // A JPEG that never reaches a frame header.
            ("endless.jpg", vec![0xFF, 0xD8, 0xFF, 0xE0, 0xFF, 0xFF]),
            // A TIFF whose directory offset points past the end of the file.
            ("wild.tif", b"II\x2a\x00\xff\xff\xff\x7f".to_vec()),
            ("short.webp", b"RIFF\x04\x00\x00\x00WEBPVP8X".to_vec()),
        ];
        for (name, bytes) in cases {
            assert!(
                measure(&td, name, bytes).is_err(),
                "{name} should have been refused, not measured"
            );
        }
    }
}

files.src/files/mod.rs:
//! The filesystem, as tiny sees it.
//!
//! Three separate questions about things on disk:
//!
//! - [`project`] — what `tiny <thing>` meant, answered once at startup.
//! - [`tree`] — the directory model the left pane walks, loaded lazily and
//!   refreshed on demand rather than watched.
//! - [`media`] — what a picture or a video is, and how to hand it to the
//!   desktop's own viewer.
//!
//! Nothing here writes to disk except [`project`], and only on the one path
//! where it creates the folder you asked for. File operations the user
//! triggers — new, rename, delete, copy — live in `app::fileops`,
//! because each one has a status message and an undo story attached and those
//! belong with the state they change.

pub mod media;
pub mod project;
pub mod tree;

files.src/files/project.rs:
//! Working out what `tiny <thing>` meant, and what to write if it is not
//! there yet.
//!
//! A project is a directory. That is the whole definition — no marker folder,
//! no registry, no database, and no state anywhere else on the machine. Point
//! tiny at a folder and it opens the folder; move the folder and nothing
//! breaks, because nothing ever knew where it was.
//!
//! # Nothing is written into your project
//!
//! tiny never writes a file into a folder of yours that you did not name. No
//! starter page, no dotfiles, no caches, no per-project settings — how the
//! program behaves comes from one config file per user (see
//! [`crate::config`]), never from the folder being opened. A new project is an
//! empty folder, and an existing folder of someone's work is left exactly as
//! it was found.
//!
//! # Why there is no `tiny new`
//!
//! Naming a path that does not exist creates it. That collapses "make a
//! project" and "open a project" into the same gesture, which is the whole
//! reason there is no separate subcommand. The cost is that a typo in a path
//! silently creates a directory instead of erroring — a trade the design
//! accepts, because the alternative is a `new` command nobody remembers.
//!
//! # Naming a file
//!
//! `tiny todo.txt` opens that one file in the editor with the tree beside it,
//! which is how tiny stands in for a plain text editor when a whole project is
//! more than you wanted. A name that is not on disk yet is created either way;
//! the extension is what decides which — see [`names_a_file`].

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};

use crate::config::{self, Config};

/// What to open: a directory for the tree, and optionally a file to land on.
#[derive(Debug, Clone, PartialEq)]
pub struct Target {
    pub root: PathBuf,
    /// Set when the argument named a file — the tree opens on its directory
    /// and the cursor starts on the file itself.
    pub file: Option<PathBuf>,
    /// True when this run made the directory, which is what puts the "new
    /// project" hint on the status line.
    pub created: bool,
}

/// Turn the command-line argument into something to open, creating whatever
/// is named if it does not exist yet.
///
/// - no argument: the working directory
/// - a directory: itself
/// - a file: its folder, with the file in the editor
/// - a name that does not exist, with an extension: an empty file, opened
/// - a name that does not exist, without one: a new folder
///
/// There is no walking up to find anything, because there is nothing to find:
/// `tiny` opens where you are standing, and `tiny some/folder` opens that
/// folder. Nothing on disk marks one directory as more of a project than
/// another.
///
/// Everything is canonicalized before it is returned, so the rest of the
/// program can compare paths with `==` and use `strip_prefix` against the root
/// without worrying about `./`, symlinks, or relative segments. `tree`,
/// `search` and `graph` all rely on that being true.
pub fn resolve(arg: Option<&str>, cfg: &Config) -> Result<Target> {
    let (mut root, file, created) = match arg {
        None => {
            let cwd = std::env::current_dir().unwrap_or_else(|_| cfg.default_root.clone());
            (cwd, None, false)
        }
        Some(a) => {
            let path = expand(a);
            if path.is_file() {
                (folder_of(&path), Some(path), false)
            } else if path.is_dir() {
                (path, None, false)
            } else if names_a_file(a, &path) {
                // `tiny todo.txt` on a name that is not there yet writes the
                // file and edits it, rather than making a folder called
                // `todo.txt` — which is what a `.` in the name always meant.
                touch(&path)?;
                (folder_of(&path), Some(path), false)
            } else {
                // Naming somewhere that isn't there yet is how you start a
                // project now that there is no separate `new` command.
                fs::create_dir_all(&path)
                    .with_context(|| format!("cannot create {}", path.display()))?;
                (path, None, true)
            }
        }
    };

    root = canonical(&root).with_context(|| format!("cannot open {}", root.display()))?;
    let file = file.map(|f| canonical(&f).unwrap_or(f));

    Ok(Target {
        root,
        file,
        created,
    })
}

/// The folder a file argument opens the tree on: the one the file is in.
fn folder_of(file: &Path) -> PathBuf {
    // `Path::new("todo.txt").parent()` is `Some("")`, not `None`, so a bare
    // filename has to be turned into the working directory by hand.
    match file.parent() {
        Some(p) if !p.as_os_str().is_empty() => p.to_path_buf(),
        _ => PathBuf::from("."),
    }
}

/// Does a name that is not on disk yet mean a file, or a folder?
///
/// The extension decides: `todo.txt` and `scratch.py` are files, `thesis` is a
/// folder. A trailing slash always means a folder, since that is what it means
/// everywhere else. The rule mis-reads a dotted folder name like `site.v2`,
/// which is the price of not having a flag.
///
/// The same rule answers the question on the command line and at the `n`
/// prompt inside the app, which is why it lives here and is called from both:
/// one place to read, and no chance of the two disagreeing. Neither can make
/// an extensionless *file* — `*new LICENSE` is the way to do that.
pub fn names_a_file(arg: &str, path: &Path) -> bool {
    !arg.ends_with(std::path::is_separator) && path.extension().is_some()
}

/// Create an empty file, and any directories above it.
///
/// `create_new` rather than `create`: if something appeared at that path
/// between the `is_file` check in `resolve` and here, the right answer is an
/// error, not a truncated file.
fn touch(path: &Path) -> Result<()> {
    if let Some(dir) = path.parent().filter(|p| !p.as_os_str().is_empty()) {
        fs::create_dir_all(dir).with_context(|| format!("cannot create {}", dir.display()))?;
    }
    fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(path)
        .with_context(|| format!("cannot create {}", path.display()))?;
    Ok(())
}

/// Expand a leading `~`, which the shell leaves alone inside quotes.
///
/// Needed because `tiny "~/notes"` and `tiny '~/notes'` reach us with a
/// literal tilde — the shell only expands it unquoted, and cmd.exe never does.
/// Deliberately handles just `~` and `~/...`; `~otheruser` is not supported and
/// is left as a literal path, which will simply fail to open.
fn expand(s: &str) -> PathBuf {
    let tail = if s == "~" {
        Some("")
    } else {
        s.strip_prefix("~/").or_else(|| s.strip_prefix("~\\"))
    };
    match tail.zip(config::home_dir()) {
        Some(("", home)) => home,
        Some((rest, home)) => home.join(rest),
        None => PathBuf::from(s),
    }
}

/// `canonicalize`, spelled the way the rest of the system expects to read it.
///
/// On Windows the standard library's answer is a *verbatim* path — `\\?\C:\x`
/// rather than `C:\x`. The file APIs take it happily, which is why it goes
/// unnoticed until something else is handed one: git given it as a working
/// directory, `cmd /C start` given it as a file to open, a path from git that
/// has to be compared with it. None of those agree it is the same place.
///
/// So the prefix comes off wherever that is safe, which is what the `dunce`
/// crate does and the reason it exists — a dozen lines are not worth a
/// dependency. Everywhere else this is `canonicalize` and nothing more.
pub fn canonical(path: &Path) -> std::io::Result<PathBuf> {
    let resolved = path.canonicalize()?;
    if cfg!(windows)
        && let Some(plain) = resolved.to_str().and_then(strip_verbatim)
    {
        return Ok(PathBuf::from(plain));
    }
    Ok(resolved)
}

/// `\\?\C:\x` as `C:\x`, when dropping the prefix changes nothing.
///
/// Only an ordinary drive path qualifies. A `\\?\UNC\` share, anything past the
/// old 260-character limit, and a name Windows reserves for a device (`CON`,
/// `NUL`, `COM1`…) all genuinely need the prefix to mean what they say.
///
/// Plain text in and out rather than a `Path`, so it is compiled and tested on
/// every platform — not only on the one where it is ever called.
fn strip_verbatim(s: &str) -> Option<&str> {
    let rest = s.strip_prefix(r"\\?\")?;
    let b = rest.as_bytes();
    let drive = b.len() >= 3 && b[0].is_ascii_alphabetic() && b[1] == b':' && b[2] == b'\\';
    if !drive || rest.len() >= 260 {
        return None;
    }
    let reserved = rest.split('\\').any(|part| {
        let stem = part
            .split('.')
            .next()
            .unwrap_or("")
            .trim_end()
            .to_ascii_uppercase();
        let numbered = |device: &str| {
            stem.strip_prefix(device)
                .is_some_and(|n| n.len() == 1 && matches!(n.as_bytes()[0], b'1'..=b'9'))
        };
        matches!(stem.as_str(), "CON" | "PRN" | "AUX" | "NUL") || numbered("COM") || numbered("LPT")
    });
    (!reserved).then_some(rest)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn cfg() -> Config {
        Config::default()
    }

    /// Every visible and hidden name directly inside `dir`.
    fn listing(dir: &Path) -> Vec<String> {
        let mut names: Vec<String> = fs::read_dir(dir)
            .unwrap()
            .flatten()
            .map(|e| e.file_name().to_string_lossy().into_owned())
            .collect();
        names.sort();
        names
    }

    #[test]
    fn a_missing_path_becomes_a_new_folder_with_nothing_in_it() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("project1");
        let t = resolve(Some(path.to_str().unwrap()), &cfg()).unwrap();

        assert!(t.created);
        assert!(t.root.is_dir(), "the folder is made");
        assert!(
            listing(&t.root).is_empty(),
            "and left empty — tiny writes no starter page"
        );
        assert_eq!(t.file, None, "so there is nothing to open on");
    }

    #[test]
    fn an_existing_folder_of_work_is_left_exactly_as_it_was() {
        let td = tempfile::tempdir().unwrap();
        let root = td.path().join("existing");
        fs::create_dir(&root).unwrap();
        fs::write(root.join("thesis.txt"), "words").unwrap();

        let t = resolve(Some(root.to_str().unwrap()), &cfg()).unwrap();
        assert_eq!(
            listing(&t.root),
            ["thesis.txt"],
            "no README, and above all no dotfiles"
        );
        assert!(!t.created);
    }

    #[test]
    fn a_freshly_cloned_folder_is_opened_without_gaining_anything() {
        let td = tempfile::tempdir().unwrap();
        let root = td.path().join("fresh-clone");
        fs::create_dir_all(root.join(".git")).unwrap();

        let t = resolve(Some(root.to_str().unwrap()), &cfg()).unwrap();
        assert!(!t.created, "the folder was already there");
        assert_eq!(listing(&t.root), [".git"], "and is untouched");
    }

    #[test]
    fn opening_the_same_new_folder_twice_writes_nothing_either_time() {
        let td = tempfile::tempdir().unwrap();
        let root = td.path().join("twice");
        resolve(Some(root.to_str().unwrap()), &cfg()).unwrap();
        fs::write(root.join("mine.md"), "# mine\n").unwrap();

        let t = resolve(Some(root.to_str().unwrap()), &cfg()).unwrap();
        assert!(!t.created, "it is not new the second time");
        assert_eq!(
            listing(&t.root),
            ["mine.md"],
            "and the note written into it is the only thing there"
        );
    }

    #[test]
    fn a_folder_is_opened_where_it_is_with_nothing_to_walk_up_to() {
        let td = tempfile::tempdir().unwrap();
        let deep = td.path().join("proj").join("src");
        fs::create_dir_all(&deep).unwrap();
        fs::write(deep.join("main.py"), "print(1)").unwrap();

        let t = resolve(Some(deep.to_str().unwrap()), &cfg()).unwrap();
        assert_eq!(t.root, canonical(&deep).unwrap());
    }

    #[test]
    fn naming_a_file_opens_its_folder_with_the_cursor_on_it() {
        let td = tempfile::tempdir().unwrap();
        let root = td.path().join("code");
        fs::create_dir(&root).unwrap();
        let file = root.join("main.py");
        fs::write(&file, "print(1)").unwrap();

        let t = resolve(Some(file.to_str().unwrap()), &cfg()).unwrap();
        assert_eq!(t.root, canonical(&root).unwrap());
        assert_eq!(t.file, Some(canonical(&file).unwrap()));
        assert_eq!(listing(&t.root), ["main.py"], "opening it wrote nothing");
    }

    #[test]
    fn naming_a_file_that_is_not_there_yet_writes_an_empty_one() {
        let td = tempfile::tempdir().unwrap();
        let root = td.path().join("scratch");
        fs::create_dir(&root).unwrap();
        let file = root.join("todo.txt");

        let t = resolve(Some(file.to_str().unwrap()), &cfg()).unwrap();
        assert!(file.is_file(), "the file is created, not a folder");
        assert_eq!(fs::read_to_string(&file).unwrap(), "");
        assert_eq!(t.root, canonical(&root).unwrap());
        assert_eq!(t.file, Some(canonical(&file).unwrap()));
        assert_eq!(
            listing(&t.root),
            ["todo.txt"],
            "asking for one file gets one file"
        );
    }

    #[test]
    fn a_new_file_brings_its_folders_with_it() {
        let td = tempfile::tempdir().unwrap();
        let file = td.path().join("a").join("b").join("notes.md");

        let t = resolve(Some(file.to_str().unwrap()), &cfg()).unwrap();
        assert!(file.is_file());
        assert_eq!(t.root, canonical(file.parent().unwrap()).unwrap());
        assert_eq!(listing(&t.root), ["notes.md"]);
    }

    #[test]
    fn an_extension_is_what_separates_a_new_file_from_a_new_folder() {
        assert!(names_a_file("todo.txt", Path::new("todo.txt")));
        assert!(names_a_file(
            "~/code/scratch.py",
            Path::new("/home/x/scratch.py")
        ));
        assert!(!names_a_file("thesis", Path::new("thesis")));
        assert!(
            !names_a_file("notes.d/", Path::new("notes.d")),
            "a trailing slash means a folder whatever the name looks like"
        );
    }

    #[test]
    fn tilde_expands_to_the_home_directory() {
        let home = config::home_dir().unwrap();
        assert_eq!(expand("~/notes"), home.join("notes"));
        assert_eq!(expand("~"), home);
        assert_eq!(
            expand("~\\notes"),
            home.join("notes"),
            "cmd.exe never expands a tilde, so the backslash form has to work too"
        );
        assert_eq!(expand("/tmp/x"), PathBuf::from("/tmp/x"));
        assert_eq!(expand("relative/x"), PathBuf::from("relative/x"));
        assert_eq!(expand("~notes"), PathBuf::from("~notes"), "not a home path");
    }

    #[test]
    fn a_verbatim_drive_path_loses_its_prefix() {
        assert_eq!(
            strip_verbatim(r"\\?\C:\Users\tj\notes"),
            Some(r"C:\Users\tj\notes")
        );
        assert_eq!(strip_verbatim(r"\\?\d:\x"), Some(r"d:\x"));
    }

    #[test]
    fn a_path_that_needs_its_prefix_keeps_it() {
        assert_eq!(
            strip_verbatim(r"C:\already\plain"),
            None,
            "nothing to strip"
        );
        assert_eq!(
            strip_verbatim(r"\\?\UNC\server\share\x"),
            None,
            "a network share"
        );
        assert_eq!(strip_verbatim(r"\\?\C:\dir\NUL"), None, "a device name");
        assert_eq!(
            strip_verbatim(r"\\?\C:\dir\con.txt"),
            None,
            "even with an extension"
        );
        assert_eq!(strip_verbatim(r"\\?\C:\dir\COM1"), None);
        assert_eq!(
            strip_verbatim(r"\\?\C:\dir\COM0"),
            Some(r"C:\dir\COM0"),
            "there is no COM0"
        );
        assert_eq!(
            strip_verbatim(r"\\?\C:\dir\console"),
            Some(r"C:\dir\console"),
            "a longer name is only a name"
        );
        let long = format!(r"\\?\C:\{}", "a".repeat(300));
        assert_eq!(strip_verbatim(&long), None, "past the old path limit");
    }
}

files.src/files/tree.rs:
//! The project tree: a lazily-loaded directory model plus the flattening
//! step that turns it into the list of rows the left pane draws.
//!
//! Children are read from disk only when a directory is first expanded, so
//! opening a project with a deep `node_modules` in it stays instant.
//!
//! # The two shapes
//!
//! There are deliberately two representations of the same thing:
//!
//! - [`Node`] is the **tree**: nested, mutable, and the source of truth for
//!   which directories are open and which have been read.
//! - [`Row`] is the **list**: one flat entry per visible line, produced by
//!   [`Tree::flatten`], carrying a precomputed `depth` for indentation.
//!
//! `app` holds the flattened rows and indexes into them with a single `usize`
//! cursor; `ui` draws a window of them. Nothing outside this module walks the
//! nested form. That means every structural change — expand, collapse,
//! refresh — has to be followed by a re-flatten, which `App::rebuild_rows`
//! does while preserving the cursor by path rather than by index.
//!
//! # Who asks it to re-read
//!
//! The tree never watches anything itself: it re-reads when something asks it
//! to. That is a create/rename/delete, a `.`-toggle, `*reload`, or — twice a second
//! while tiny is idle — [`app`'s disk watcher](crate::app), which stats the
//! directories [`Tree::loaded_dirs`] names and calls [`Tree::refresh_all`] when
//! one of them has a new modification time. There is still no inotify and no
//! background thread; see `app::watch` for why polling was the cheaper answer.

use std::cmp::Ordering;
use std::fs;
use std::path::{Path, PathBuf};

/// One entry in the nested tree. Directories own their `children`, which stay
/// empty until the directory is first expanded.
#[derive(Debug, Clone)]
pub struct Node {
    /// Absolute path. Canonicalized at the root, so it is safe to compare with
    /// `==` and to `strip_prefix` against `Tree::root_path`.
    pub path: PathBuf,
    /// Just the final component, cached so drawing does not re-derive it.
    pub name: String,
    pub is_dir: bool,
    /// Whether the user has opened this directory. Independent of `loaded`: a
    /// directory can be read but collapsed, which is what happens when you
    /// expand something and then close it again.
    pub expanded: bool,
    /// Whether `children` has been read from disk yet.
    pub loaded: bool,
    /// Set when the directory exists but could not be read (permissions, etc).
    pub unreadable: bool,
    /// Populated only once `loaded` is true. Empty for files, and for
    /// directories that have never been opened.
    pub children: Vec<Node>,
}

impl Node {
    fn new(path: PathBuf, is_dir: bool) -> Self {
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().into_owned())
            // A root like `/` has no file_name; show the path itself.
            .unwrap_or_else(|| path.to_string_lossy().into_owned());
        Self {
            path,
            name,
            is_dir,
            expanded: false,
            loaded: false,
            unreadable: false,
            children: Vec::new(),
        }
    }
}

/// One visible line in the tree pane.
///
/// A flattened snapshot of a [`Node`], not a reference to one — `app` keeps a
/// `Vec<Row>` and indexes it by cursor position, so rows have to outlive any
/// borrow of the tree. Cloning the path and name on every flatten is the price
/// of that, and it is cheap next to the disk read that produced them.
#[derive(Debug, Clone, PartialEq)]
pub struct Row {
    pub path: PathBuf,
    pub name: String,
    /// Nesting level, with the project root at 0. Drawing multiplies this by
    /// the indent width; nothing else uses it.
    pub depth: usize,
    pub is_dir: bool,
    pub expanded: bool,
    pub unreadable: bool,
}

/// The directory model. Owns the root [`Node`] and the dotfile setting that
/// governs every read.
pub struct Tree {
    root: Node,
    show_hidden: bool,
}

impl Tree {
    /// Build a tree rooted at `path` with its top level already loaded.
    ///
    /// The root is forced to `is_dir` and `expanded` regardless of what is on
    /// disk: the project root is always a directory and is always open, so
    /// there is no state in which the tree pane can be empty of context.
    pub fn new(path: PathBuf, show_hidden: bool) -> Self {
        let mut root = Node::new(path, true);
        root.is_dir = true;
        root.expanded = true;
        let mut tree = Self { root, show_hidden };
        tree.load_children_at(&tree.root.path.clone());
        tree
    }

    pub fn root_path(&self) -> &Path {
        &self.root.path
    }

    pub fn show_hidden(&self) -> bool {
        self.show_hidden
    }

    /// Toggle dotfile visibility. Loaded directories are re-read so the
    /// newly-visible entries appear without a manual refresh.
    pub fn set_show_hidden(&mut self, show: bool) {
        if self.show_hidden != show {
            self.show_hidden = show;
            self.refresh_all();
        }
    }

    /// Depth-first walk producing the rows to draw, in display order.
    ///
    /// Called after every structural change, and its result is what the cursor
    /// indexes into. Cost is proportional to the number of *visible* rows, not
    /// to the size of the project, because collapsed directories are not
    /// descended into.
    pub fn flatten(&self) -> Vec<Row> {
        let mut out = Vec::new();
        // The root itself is row 0, so the project name is always on screen.
        out.push(Row {
            path: self.root.path.clone(),
            name: self.root.name.clone(),
            depth: 0,
            is_dir: true,
            expanded: self.root.expanded,
            unreadable: self.root.unreadable,
        });
        if self.root.expanded {
            push_rows(&self.root.children, 1, &mut out);
        }
        out
    }

    /// Locate a node by absolute path, walking down from the root one
    /// component at a time.
    ///
    /// Returns `None` for anything outside the root, and for anything inside a
    /// directory that has not been loaded yet — an unloaded directory has no
    /// children to find, even though the file exists on disk. Callers that
    /// need the node to exist have to `expand` the parents first; that is what
    /// `App::reveal` does.
    pub fn find(&self, path: &Path) -> Option<&Node> {
        let rel = path.strip_prefix(&self.root.path).ok()?;
        let mut node = &self.root;
        for part in rel.components() {
            let name = part.as_os_str();
            node = node
                .children
                .iter()
                .find(|c| c.path.file_name() == Some(name))?;
        }
        Some(node)
    }

    /// Mutable twin of [`Tree::find`]. Duplicated rather than generic because
    /// threading mutability through a shared walk needs either unsafe code or
    /// a macro, and neither is worth it for twelve lines.
    fn find_mut(&mut self, path: &Path) -> Option<&mut Node> {
        let rel = path.strip_prefix(&self.root.path).ok()?.to_path_buf();
        let mut node = &mut self.root;
        for part in rel.components() {
            let name = part.as_os_str().to_os_string();
            node = node
                .children
                .iter_mut()
                .find(|c| c.path.file_name() == Some(name.as_os_str()))?;
        }
        Some(node)
    }

    /// Expand a directory, reading it from disk if this is the first time.
    /// No-op for files. Returns true if anything changed.
    pub fn expand(&mut self, path: &Path) -> bool {
        let needs_load = match self.find(path) {
            Some(n) if n.is_dir => !n.loaded,
            _ => return false,
        };
        if needs_load {
            self.load_children_at(path);
        }
        match self.find_mut(path) {
            Some(n) => {
                let changed = !n.expanded;
                n.expanded = true;
                changed
            }
            None => false,
        }
    }

    /// Close a directory. Its children stay in memory, so reopening it is
    /// instant and does not touch the disk. Returns true if anything changed.
    pub fn collapse(&mut self, path: &Path) -> bool {
        match self.find_mut(path) {
            Some(n) if n.is_dir && n.expanded => {
                n.expanded = false;
                true
            }
            _ => false,
        }
    }

    /// Expand a collapsed directory or collapse an expanded one. This is what
    /// Enter does in the tree pane.
    pub fn toggle(&mut self, path: &Path) -> bool {
        match self.find(path) {
            Some(n) if n.is_dir && n.expanded => self.collapse(path),
            Some(n) if n.is_dir => self.expand(path),
            _ => false,
        }
    }

    /// Re-read every directory that has been loaded so far.
    ///
    /// The blunt instrument behind `R`, `:reload`, and every file operation.
    /// Cost is one `read_dir` per open directory — fine for a project you are
    /// looking at, and the reason unopened directories are skipped entirely.
    pub fn refresh_all(&mut self) {
        let dirs = self.loaded_dirs();
        for d in dirs {
            self.load_children_at(&d);
        }
    }

    /// Paths of every currently-loaded directory, parents before children so
    /// a refresh pass rebuilds the tree top-down.
    ///
    /// Also what `app`'s disk watcher stats: these are exactly the directories
    /// whose contents are on screen, so they are exactly the ones where an
    /// entry appearing or disappearing has to be noticed.
    pub fn loaded_dirs(&self) -> Vec<PathBuf> {
        fn walk(n: &Node, out: &mut Vec<PathBuf>) {
            if n.is_dir && n.loaded {
                out.push(n.path.clone());
                for c in &n.children {
                    walk(c, out);
                }
            }
        }
        let mut out = Vec::new();
        walk(&self.root, &mut out);
        out
    }

    /// Read `dir` from disk and merge the result into the tree, carrying over
    /// the expansion state of any subdirectory that still exists.
    ///
    /// The merge is what makes refresh non-destructive. A naive re-read would
    /// collapse everything the user had opened; instead each fresh entry looks
    /// for its predecessor by name and inherits `expanded`, `loaded` and the
    /// whole subtree from it. Entries that vanished from disk are simply not
    /// in the fresh list, so they disappear; new ones arrive collapsed.
    ///
    /// The `prev.is_dir == fresh_child.is_dir` guard handles the case where a
    /// name was deleted and recreated as the other kind — inheriting a
    /// directory's children onto a file would be nonsense.
    ///
    /// A read failure is recorded as `unreadable` rather than propagated: a
    /// permission-denied directory should draw dimmed in the tree, not stop
    /// the program.
    fn load_children_at(&mut self, dir: &Path) {
        let show_hidden = self.show_hidden;
        let fresh = read_dir_sorted(dir, show_hidden);
        let Some(node) = self.find_mut(dir) else {
            return;
        };
        match fresh {
            Ok(entries) => {
                let old = std::mem::take(&mut node.children);
                node.children = entries
                    .into_iter()
                    .map(|mut fresh_child| {
                        if let Some(prev) = old.iter().find(|o| o.name == fresh_child.name) {
                            // Same entry as before: keep what the user had open.
                            if prev.is_dir == fresh_child.is_dir {
                                fresh_child.expanded = prev.expanded;
                                fresh_child.loaded = prev.loaded;
                                fresh_child.unreadable = prev.unreadable;
                                fresh_child.children = prev.children.clone();
                            }
                        }
                        fresh_child
                    })
                    .collect();
                node.loaded = true;
                node.unreadable = false;
            }
            Err(_) => {
                node.children.clear();
                node.loaded = true;
                node.unreadable = true;
            }
        }
    }
}

/// Recursive half of [`Tree::flatten`]: append `nodes` and, for any that are
/// open, their children one level deeper.
fn push_rows(nodes: &[Node], depth: usize, out: &mut Vec<Row>) {
    for n in nodes {
        out.push(Row {
            path: n.path.clone(),
            name: n.name.clone(),
            depth,
            is_dir: n.is_dir,
            expanded: n.expanded,
            unreadable: n.unreadable,
        });
        if n.is_dir && n.expanded {
            push_rows(&n.children, depth + 1, out);
        }
    }
}

/// Directories first, then case-insensitive name; ties broken by the raw name
/// so the order is stable between reads.
///
/// The tiebreak matters more than it looks: `read_dir` returns entries in
/// whatever order the filesystem feels like, and without a total ordering
/// `README` and `readme` could swap places between refreshes, moving rows out
/// from under the cursor.
///
/// Individual failing entries are skipped rather than failing the whole read,
/// so one bad inode does not hide a directory's other contents.
fn read_dir_sorted(dir: &Path, show_hidden: bool) -> std::io::Result<Vec<Node>> {
    let mut out = Vec::new();
    for entry in fs::read_dir(dir)? {
        let Ok(entry) = entry else { continue };
        let name = entry.file_name().to_string_lossy().into_owned();
        if !show_hidden && name.starts_with('.') {
            continue;
        }
        // `file_type` avoids following symlinks; a broken link still lists.
        let is_dir = match entry.file_type() {
            Ok(ft) if ft.is_symlink() => entry.path().is_dir(),
            Ok(ft) => ft.is_dir(),
            Err(_) => false,
        };
        out.push(Node::new(entry.path(), is_dir));
    }
    out.sort_by(|a, b| match (a.is_dir, b.is_dir) {
        (true, false) => Ordering::Less,
        (false, true) => Ordering::Greater,
        _ => a
            .name
            .to_lowercase()
            .cmp(&b.name.to_lowercase())
            .then_with(|| a.name.cmp(&b.name)),
    });
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Build a throwaway project directory for a test.
    fn fixture() -> tempfile::TempDir {
        let td = tempfile::tempdir().unwrap();
        let r = td.path();
        fs::create_dir(r.join("src")).unwrap();
        fs::create_dir(r.join("notes")).unwrap();
        fs::create_dir(r.join("notes").join("deep")).unwrap();
        fs::write(r.join("notes").join("deep").join("buried.md"), "x").unwrap();
        fs::write(r.join("src").join("main.py"), "print(1)").unwrap();
        fs::write(r.join("README.md"), "# hi").unwrap();
        fs::write(r.join(".hidden"), "secret").unwrap();
        td
    }

    fn names(rows: &[Row]) -> Vec<String> {
        rows.iter().map(|r| r.name.clone()).collect()
    }

    #[test]
    fn root_loads_sorted_dirs_first_and_hides_dotfiles() {
        let td = fixture();
        let tree = Tree::new(td.path().to_path_buf(), false);
        let rows = tree.flatten();
        // Row 0 is the project root itself.
        assert_eq!(names(&rows)[1..], ["notes", "src", "README.md"]);
    }

    #[test]
    fn show_hidden_reveals_dotfiles() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        assert!(!names(&tree.flatten()).contains(&".hidden".to_string()));
        tree.set_show_hidden(true);
        assert!(names(&tree.flatten()).contains(&".hidden".to_string()));
    }

    #[test]
    fn children_load_lazily_on_expand() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        let src = td.path().join("src");
        assert!(!tree.find(&src).unwrap().loaded, "not read until expanded");
        assert_eq!(tree.flatten().len(), 4);

        tree.expand(&src);
        assert!(tree.find(&src).unwrap().loaded);
        assert_eq!(
            names(&tree.flatten())[1..],
            ["notes", "src", "main.py", "README.md"]
        );
    }

    #[test]
    fn toggle_expands_then_collapses() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        let notes = td.path().join("notes");
        tree.toggle(&notes);
        assert!(tree.find(&notes).unwrap().expanded);
        tree.toggle(&notes);
        assert!(!tree.find(&notes).unwrap().expanded);
        // Collapsed children stay out of the row list.
        assert_eq!(tree.flatten().len(), 4);
    }

    #[test]
    fn expanding_a_file_is_a_noop() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        assert!(!tree.expand(&td.path().join("README.md")));
        assert!(!tree.toggle(&td.path().join("README.md")));
    }

    #[test]
    fn refresh_picks_up_new_files_and_keeps_expansion_state() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        let notes = td.path().join("notes");
        let deep = notes.join("deep");
        tree.expand(&notes);
        tree.expand(&deep);
        assert!(names(&tree.flatten()).contains(&"buried.md".to_string()));

        fs::write(notes.join("new.md"), "fresh").unwrap();
        tree.refresh_all();

        let after = names(&tree.flatten());
        assert!(after.contains(&"new.md".to_string()), "new file appears");
        assert!(
            after.contains(&"buried.md".to_string()),
            "nested expansion survives a refresh of the parent"
        );
    }

    #[test]
    fn refresh_drops_deleted_entries() {
        let td = fixture();
        let mut tree = Tree::new(td.path().to_path_buf(), false);
        fs::remove_file(td.path().join("README.md")).unwrap();
        tree.refresh_all();
        assert!(!names(&tree.flatten()).contains(&"README.md".to_string()));
    }

    #[test]
    fn find_returns_none_for_paths_outside_the_root() {
        let td = fixture();
        let tree = Tree::new(td.path().to_path_buf(), false);
        assert!(tree.find(Path::new("/definitely/not/here")).is_none());
    }
}

