    Bound(&[Action::Copy, Action::Paste], "copy | paste"),
    Bound(&[Action::TreeHidden], "show dotfiles"),
    Blank,
    Heading("THE BAR"),
    Bound(&[Action::Bar], "search — star first, a command"),
    Bound(&[Action::Help], "this window"),
    Blank,
